import{_ as p,a0 as l,w as o,s as d,ao as c,I as i,x as s,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 at 命令在 Linux 上安排任務 | LCTT x X-CMD","titleTemplate":false,"description":"使用 at 命令在 Linux 上安排任務 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 at 命令在 Linux 上安排任務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 at 命令在 Linux 上安排任務 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200403 Scheduling tasks on Linux using the at command","title":"使用 at 命令在 Linux 上安排任務","tag":"202004","desc":""},"relativePath":"202004/20200403 Scheduling tasks on Linux using the at command.md","filePath":"[post].md"}'),r={name:"202004/20200403 Scheduling tasks on Linux using the at command.md"};function h(g,a,u,k,b,m){const n=l("Link");return o(),d("div",null,[a[15]||(a[15]=c(`<h1 id="使用-at-命令在-linux-上安排任務" tabindex="-1">使用 at 命令在 Linux 上安排任務 <a class="header-anchor" href="#使用-at-命令在-linux-上安排任務" aria-label="Permalink to “使用 at 命令在 Linux 上安排任務”">​</a></h1><blockquote><p>at 命令可以很容易地安排 Linux 任務在你選擇的任何時間或日期運行，讓我們來看看它能為你做什麼。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/08/gettyimages-140389307-100808283-large.jpg" alt=""></p><p>當你希望命令或腳本在某個特定時間運行時，你不需要將手指放在鍵盤上盤旋等待按下回車鍵，或者是在特定時間坐在辦公桌前。相反，你可以通過 <code>at</code> 命令來設置任務。在本文中，我們將研究如何使用 <code>at</code> 來安排任務，如何精確地選擇任務希望運行的時間，以及如何使用 <code>at</code> 來查看安排運行的任務。</p><h3 id="at-vs-cron" tabindex="-1">at vs cron <a class="header-anchor" href="#at-vs-cron" aria-label="Permalink to “at vs cron”">​</a></h3><p>對於那些使用 cron 在 Linux 系統上安排任務的人來説，<code>at</code> 命令類似於 cron，因為你可以在選定的時間調度任務，但是 cron 用於定期運行的作業 —— 甚至是每年僅一次。大多數 cron 作業的頻率都設置為每天、每週或每月運行一次，不過你可以控制運行的頻率和時間。</p><p>另一方面，<code>at</code> 命令用於僅運行一次的任務。想在午夜重啓系統？沒問題，只要你有適當的權限，<code>at</code> 可以為你完成此操作。如果你希望系統在每個星期六凌晨 2 點重啓，那麼改用 cron。</p><h3 id="使用-at" tabindex="-1">使用 at <a class="header-anchor" href="#使用-at" aria-label="Permalink to “使用 at”">​</a></h3><p><code>at</code> 命令很容易使用，只需記住幾件事。一個簡單使用 <code>at</code> 的例子類似於這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 5:00PM</span></span>
<span class="line"><span>at&gt; date &gt;&gt; thisfile</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span></code></pre></div><p>在輸入 <code>at</code> 和應該運行命令的時間，<code>at</code> 會提示你在設定時間會運行該命令（此例中是 <code>date</code> 命令）。輸入 <code>^D</code>（<code>Ctrl + d</code>）來完成請求。</p><p>假設我們在下午 5 點之前設置這個 <code>at</code> 命令，那麼這個日期和時間將在當天下午 5 點添加到名為 <code>thisfile</code> 文件的末尾。否則，該命令將在第二天下午 5 點運行。</p><p>與 <code>at</code> 命令進行交互時，可以輸入多個命令。如果你要同時運行多個命令，只需輸入多個命令列即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 6:22</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; echo first &gt;&gt; thisfile</span></span>
<span class="line"><span>at&gt; echo second &gt;&gt; thisfile</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span></code></pre></div><p>在上面的命令中，我們使用了一個普通的用户賬户，將一些簡單的文本添加到該用户主目錄的文件中。如果在上午 6:22 之後運行這些命令，那麼命令會在第二天運行，因為 6:22 表示上午 6:22。如果你想在下午 6:22 運行，使用 <code>6:22 PM</code> 或者 <code>18:22</code>。<code>6:22 PM</code> 這樣也是可以工作的。</p><p>你也可以通過使用 <code>at</code> 來安排命令在指定的日期或時間運行，例如 <code>10:00AM April 15 2021</code> 或 <code>noon + 5 days</code>（從今天起 5 天內的中午運行），以下是一些例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>at 6PM tomorrow</span></span>
<span class="line"><span>at noon April 15 2021</span></span>
<span class="line"><span>at noon + 5 days</span></span>
<span class="line"><span>at 9:15 + 1000 days</span></span></code></pre></div><p>在指定要運行的命令並按下 <code>^D</code> 後，你會注意到 <code>at</code> 命令為每個請求分配了一個作業編號，這個數字將顯示在 <code>at</code> 命令的作業隊列中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at noon + 1000 days</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; date &gt;&gt; thisfile</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span>
<span class="line"><span>job 36 at Tue Dec 27 12:00:00 2022        &lt;== job # is 36</span></span></code></pre></div><h3 id="檢查隊列" tabindex="-1">檢查隊列 <a class="header-anchor" href="#檢查隊列" aria-label="Permalink to “檢查隊列”">​</a></h3><p>你可以使用 <code>atq</code>（at queue）命令來查看 <code>at</code> 作業隊列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ atq</span></span>
<span class="line"><span>32      Thu Apr  2 03:06:00 2020 a shs</span></span>
<span class="line"><span>35      Mon Apr  6 12:00:00 2020 a shs</span></span>
<span class="line"><span>36      Tue Dec 27 12:00:00 2022 a shs</span></span>
<span class="line"><span>34      Thu Apr  2 18:00:00 2020 a shs</span></span></code></pre></div><p>如果你需要取消隊列中的一個作業，使用 <code>atrm</code>（at remove）命令和作業編號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ atrm 32</span></span>
<span class="line"><span>$ atq</span></span>
<span class="line"><span>35      Mon Apr  6 12:00:00 2020 a shs</span></span>
<span class="line"><span>36      Tue Dec 27 12:00:00 2022 a shs</span></span>
<span class="line"><span>34      Thu Apr  2 18:00:00 2020 a shs</span></span></code></pre></div><p>你可以使用 <code>at -c</code> 命令來查看安排任務的詳細信息，其它詳細信息（活動的搜索路徑等）也可以看到，但是輸出的最後一行將顯示計劃運行的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at -c 36 | tail -6</span></span>
<span class="line"><span>cd /home/shs || {</span></span>
<span class="line"><span>         echo &#39;Execution directory inaccessible&#39; &gt;&amp;2</span></span>
<span class="line"><span>         exit 1</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>date &gt;&gt; thisfile</span></span></code></pre></div><p>注意，該命令顯示首先會測試是否可以通過 <code>cd</code> 命令進入用户目錄。如果不可以，作業將退出並顯示錯誤。如果可以，則運行在 <code>at</code> 中指定的命令。它將命令視為 “進入 <code>/home/shs</code> 或退出並顯示錯誤”。</p><h3 id="以-root-身份運行作業" tabindex="-1">以 root 身份運行作業 <a class="header-anchor" href="#以-root-身份運行作業" aria-label="Permalink to “以 root 身份運行作業”">​</a></h3><p>要以 root 身份運行 <code>at</code> 作業，只需將 <code>sudo</code> 與你的 <code>at</code> 命令一起使用，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo at 8PM</span></span>
<span class="line"><span>[sudo] password for shs:</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; reboot now</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span>
<span class="line"><span>job 37 at Wed Apr  1 16:00:00 2020</span></span></code></pre></div><p>注意，root 的任務以 <code>root</code> 作為執行者顯示在隊列中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>35      Mon Apr  6 12:00:00 2020 a shs</span></span>
<span class="line"><span>36      Tue Dec 27 12:00:00 2022 a shs</span></span>
<span class="line"><span>37      Wed Apr  1 20:00:00 2020 a root         &lt;==</span></span></code></pre></div><h3 id="運行腳本" tabindex="-1">運行腳本 <a class="header-anchor" href="#運行腳本" aria-label="Permalink to “運行腳本”">​</a></h3><p>你還可以使用 <code>at</code> 命令來運行腳本，這裏有一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 4:30PM</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; bin/tryme</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span></code></pre></div><h3 id="禁止使用-at-命令" tabindex="-1">禁止使用 at 命令 <a class="header-anchor" href="#禁止使用-at-命令" aria-label="Permalink to “禁止使用 at 命令”">​</a></h3><p><code>/etc/at.deny</code> 文件提供了一種禁止用户使用 <code>at</code> 命令的方法。默認情況下，它可能會包含一個不允許的賬户列表，例如 <code>ftp</code> 和 <code>nobody</code>。可以使用 <code>/etc/at.allow</code> 文件執行相反的操作，但是通常只配置 <code>at.deny</code> 文件。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>當你要安排一項一次性任務時，無論你是希望在今天下午或幾年後運行，<code>at</code> 命令都是通用且易於使用的。</p><hr>`,40)),i("p",null,[a[1]||(a[1]=s("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3535808/scheduling-tasks-on-linux-using-the-at-command.html"},{default:t(()=>[...a[0]||(a[0]=[s("https://www.networkworld.com/article/3535808/scheduling-tasks-on-linux-using-the-at-command.html",-1)])]),_:1})]),i("p",null,[a[6]||(a[6]=s("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...a[2]||(a[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),a[7]||(a[7]=s(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[3]||(a[3]=[s("lujun9972",-1)])]),_:1}),a[8]||(a[8]=s(" 譯者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:t(()=>[...a[4]||(a[4]=[s("MjSeven",-1)])]),_:1}),a[9]||(a[9]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...a[5]||(a[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[12]||(a[12]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...a[11]||(a[11]=[s("Linux中國",-1)])]),_:1}),a[14]||(a[14]=s(" 榮譽推出",-1))])])}const C=p(r,[["render",h]]);export{y as __pageData,C as default};
